-- 296_every_lesson_animated.sql
--
-- EVERY LESSON GETS ITS FRIEND, IN CODE, FOR NOTHING.
--
-- Justin, 13 September 2026: "make sure all lessons now flow, have enough
-- animations to make super engaging." The audit behind this migration
-- (plans/week-of-2026-09-14-every-lesson-animated-plan.md): one lesson has a
-- full set of animated beats, four have one, twenty have none, and the
-- Higgsfield balance is 72 credits, which is one eight second clip. So the
-- beats are data, and the player draws them: a digi slide that names a
-- Planet Friend is rendered by CharacterBeat in the friend's own plate and
-- register, and a star breath that names a friend is led by that friend.
--
-- THREE BEATS PER LESSON, IN THE PILOT'S OWN SHAPE (ks3-12 is untouched):
--
--   arrival  after the title, starter phase, one minute. The friend lands and
--            asks the lesson's question. Skipped on the four modules where a
--            video beat already plays there (ks1-03, ks2-04, ks2-06, ks2-07).
--   pause    before the first practise slide, one minute. A star breath the
--            friend leads: two breaths, then tell your neighbour one thing
--            that surprised you and write it on your sheet. The council counts
--            an interactive as the class acting, so this beat can only shorten
--            a passive stretch, never lengthen one.
--   mission  before DiGi closes, one minute. The friend hands the single
--            action outcome to the room. It takes its minute from the DiGi
--            close wherever the close has two or more, so the last stretch of
--            watching stays inside the council's four minutes and the lesson
--            total moves by the arrival and the pause only.
--
-- THE TITLE SLIDE STOPS LYING. Seven lessons opened on the wrong friend and
-- three on a coin flip, because the title key was a July slot name (football,
-- dance, celebrate) or a name the intro map had never heard of. Every title
-- key is rewritten to the friend's real CharacterKey here, the pilot's too.
-- The KS5 titles keep Cosmo, which Justin approved on 30 August. The DSL
-- modules and ks3-14 open on DiGi with a quieter hello than DiGi's usual line.
--
-- WHAT THE DO BLOCK GUARDS, and every one of them rolls the whole thing back:
--   0. exactly 24 beat rows, and the pilot is not among them
--   1. no dash in any new copy
--   2. every module has a title, a practise phase, and closes on DiGi
--   3. an arrival is added exactly where no video beat already plays
--   4. no passive stretch over four minutes afterwards, by the council's own
--      rule, and the stricter contract rule never gets worse than it was
--   5. the timing string states the new real total
--   6. the scheme grows by exactly 68 slides
--   7. every title in the scheme carries a real key
--
-- Not idempotent by construction: a second run fails guard 3 on every module
-- (the arrival slot is no longer a title followed by a non video slide once
-- the beat is in), which is the loud failure wanted rather than a doubled
-- deck. Backed up first.
--
-- Generated by scripts/gen-296.mjs from content/beats/2026-09-14-friend-beats.json.

begin;

create table if not exists schools.school_lessons_backup_296 as
  select id, module_id, slides, teacher_notes, now() as backed_up_at from schools.school_lessons;
alter table schools.school_lessons_backup_296 enable row level security;

create table schools._m296 (module_id text primary key, title_key text not null, title_line text, arrival jsonb, pause jsonb not null, mission jsonb not null);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$eyfs-01-screens-kindness$b$, $b$pebble$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"pebble","heading":"Pebble is here!","lines":["Hello everyone! I am Pebble.","Some things on a screen are real. Some are made up. Can you tell which is which?","Let us find out together!"],"script":"Let Pebble land and say the lines. Then read the question on the wall once, in your own voice, and leave it hanging. Do not answer it. The next slide says what today is for, and the class talks before anyone is told."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"pebble","register":"bouncy","heading":"Half time! Everyone together","prompt":"Breathe in as Pebble grows. Breathe out as Pebble shrinks. Then tell the person next to you one thing you found out today, and draw or write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Pebble grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"pebble","heading":"Pebble's job for you","lines":["Here is your job. Next time a screen shows you something and you are not sure...","Stop. Look. Ask a grown up.","Then you will know. Off you go!"],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks1-02-kind-screens-calm-bodies$b$, $b$pebble$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"pebble","heading":"Pebble is here!","lines":["Hello! Pebble here.","When the screen goes off, do you ever feel wiggly? Or a bit grumpy?","Today we find out why, and what to do about it."],"script":"Let Pebble land and say the lines. Then read the question on the wall once, in your own voice, and leave it hanging. Do not answer it. The next slide says what today is for, and the class talks before anyone is told."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"pebble","register":"bouncy","heading":"Half time! Everyone together","prompt":"Breathe in as Pebble grows. Breathe out as Pebble shrinks. Then tell the person next to you one thing you found out today, and draw or write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Pebble grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"pebble","heading":"Pebble's job for you","lines":["Your job is easy to remember.","Feel it. Name it. Tell a grown up.","Try it the very next time a screen goes off!"],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks1-03-real-pretend-computer$b$, $b$pebble$b$, null, null, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"pebble","register":"bouncy","heading":"Half time! Everyone together","prompt":"Breathe in as Pebble grows. Breathe out as Pebble shrinks. Then tell the person next to you one thing you found out today, and draw or write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Pebble grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"pebble","heading":"Pebble's job for you","lines":["You are a picture detective now!","Stop and look. Then ask: real, pretend, or made by a computer?","Not sure? That is fine. Ask a grown up."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks2-04-screen-routines$b$, $b$bloop$b$, null, null, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"bloop","register":"playful","heading":"Half time · everyone together","prompt":"Two breaths: in as Bloop grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Bloop grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"bloop","heading":"Bloop's mission for you","lines":["Your mission, and it is a good one.","Build one screen routine this week: warn, finish, swap.","Stick to it for seven days and see what changes. I think you will like it."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks2-05-gaming-time-spend$b$, $b$bloop$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"bloop","heading":"Bloop arrives","lines":["Hi! Bloop here.","If a game is free, how is it making money out of you?","Great question. Let us follow the money."],"script":"Let Bloop land and say the lines. Then read the question on the wall once, in your own voice, and leave it hanging. Do not answer it. The next slide says what today is for, and the class talks before anyone is told."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"bloop","register":"playful","heading":"Half time · everyone together","prompt":"Two breaths: in as Bloop grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Bloop grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"bloop","heading":"Bloop's mission for you","lines":["Your mission.","Next time a game rushes you, hides the price, or spins a raffle, say it out loud: spend spotter!","Spotting it is the whole trick. You have got this."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks2-06-how-algorithms-work$b$, $b$digi$b$, null, null, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"digi","register":"playful","heading":"Half time · everyone together","prompt":"Two breaths: in as the star grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as the star grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"digi","heading":"DiGi's mission for you","lines":["Your mission.","Next time your feed knows what you want next, say the recipe: you watch, it learns, it serves more.","Once you can say it, it works a little less well on you."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks2-07-privacy-reputation$b$, $b$bloop$b$, null, null, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"bloop","register":"playful","heading":"Half time · everyone together","prompt":"Two breaths: in as Bloop grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Bloop grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"bloop","heading":"Bloop's mission for you","lines":["Your mission.","Before you share anything this week, run the share test. Would I shout it in assembly? Does it give away where I am? Could it hurt future me?","Three questions, ten seconds. Off you go."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks2-08-kind-safe-online$b$, $b$bloop$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"bloop","heading":"Bloop arrives","lines":["Hi! Bloop here.","What do you actually do when you see someone being torn apart online?","Most people freeze. Today you learn three moves instead."],"script":"Let Bloop land and say the lines. Then read the question on the wall once, in your own voice, and leave it hanging. Do not answer it. The next slide says what today is for, and the class talks before anyone is told."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"bloop","register":"playful","heading":"Half time · everyone together","prompt":"Two breaths: in as Bloop grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Bloop grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"bloop","heading":"Bloop's mission for you","lines":["Your mission.","Do not pile on. Save the evidence. Tell someone who can help.","You will not need them every week. But the week you do, you will be ready."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks2-09-copyright-ownership$b$, $b$orbit$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"orbit","heading":"Orbit arrives","lines":["Hello! Orbit here.","If you found it online, why is it not yours to use?","Because somebody made it. And you are a maker too, so today is about you as well."],"script":"Let Orbit land and say the lines. Then read the question on the wall once, in your own voice, and leave it hanging. Do not answer it. The next slide says what today is for, and the class talks before anyone is told."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"orbit","register":"playful","heading":"Half time · everyone together","prompt":"Two breaths: in as Orbit grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Orbit grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"orbit","heading":"Orbit's mission for you","lines":["Your mission.","Make it, it is yours. Use it, credit the maker. Copy or share it big, ask first.","Try it on the very next thing you make."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks3-10-mood-and-screens$b$, $b$orbit$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"orbit","heading":"Orbit","lines":["Orbit here.","Does this app actually leave you feeling better, or do you just keep opening it?","Honest question. Today you get a way to answer it for yourself."],"script":"Let Orbit land and say the lines. Then read the question on the wall once, in your own voice, and leave it hanging. Do not answer it. The next slide says what today is for, and the class talks before anyone is told."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"orbit","register":"level","heading":"Half time","prompt":"Two breaths with Orbit: in as it grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Orbit grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"orbit","heading":"Your mission, for one week","lines":["Close it. Ask: better, worse, or nothing? Log one word.","Do that for a week.","Then read the week back. The pattern is the answer."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks3-11-social-workarounds$b$, $b$orbit$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"orbit","heading":"Orbit","lines":["Orbit here.","What are you actually giving up when you get around the rule?","Not a lecture. A trade, and today you learn to see it."],"script":"Let Orbit land and say the lines. Then read the question on the wall once, in your own voice, and leave it hanging. Do not answer it. The next slide says what today is for, and the class talks before anyone is told."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"orbit","register":"level","heading":"Half time","prompt":"Two breaths with Orbit: in as it grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Orbit grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"orbit","heading":"Your mission","lines":["Behind every rule is a protection. Skip the rule, lose the protection.","Decide with your eyes open.","That is all anyone is asking."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks3-13-scams-fraud-money$b$, $b$orbit$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"orbit","heading":"Orbit","lines":["Orbit here.","Why would a scammer bother with you?","Because you are worth more than you think. Today, the three tells."],"script":"Let Orbit land and say the lines. Then read the question on the wall once, in your own voice, and leave it hanging. Do not answer it. The next slide says what today is for, and the class talks before anyone is told."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"orbit","register":"level","heading":"Half time","prompt":"Two breaths with Orbit: in as it grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Orbit grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"orbit","heading":"Your mission","lines":["The next message that rushes you, wants something odd, or is too good to be true: stop.","Any one of the three tells is enough to check.","Checking takes a minute. Not checking can take a lot more."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks3-14-bodies-image-pressure$b$, $b$digi$b$, $b$Hello. I am DiGi. This one matters, and we will take it steadily, together.$b$, $b${"type":"digi","phase":"starter","minutes":1,"character":"digi","heading":"DiGi opens the lesson","lines":["Hello. I am DiGi.","Why do you feel worse about yourself after scrolling?","There is an answer, and it is not about you. Let us take it steadily."],"script":"Let DiGi say the lines. Then read the question once, quietly, in your own voice, and leave it. Do not answer it. The next slide says what today is for."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"digi","register":"level","heading":"Half time","prompt":"Two breaths with the star: in as it grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as the star grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"digi","heading":"One thing to take with you","lines":["Who edited this? Who profits from me feeling worse? What would I tell my best friend?","Three questions.","Ask them for a week and notice what changes."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks4-15-manipulation-persuasion$b$, $b$nova$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"nova","heading":"Nova","lines":["Nova here.","Who decided you would want this, and what do they get if you do?","Today you learn to name the technique. Named, it loses most of its grip."],"script":"Let Nova settle and say the lines. Then read the question once, in your own voice, and leave it. Do not answer it. The next slide says what today is for."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"nova","register":"still","heading":"Half time","prompt":"Two slow breaths: in as Nova grows, out as it shrinks. Then tell your neighbour one thing from today you want to remember, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Nova grows and out as it shrinks. Then thirty seconds in pairs on one thing they want to remember, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"nova","heading":"Your mission","lines":["Notice the pull. Name it: urgency, outrage, flattery or FOMO. Follow the money.","Once a day is enough to start.","It becomes a habit faster than you would think."],"script":"The handover. Say nothing over it. When the last line lands, say it once more in your own words, level and unhurried. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks4-16-consent-images-law$b$, $b$digi$b$, $b$Hello. I am DiGi. This one matters, and we will take it steadily, together.$b$, $b${"type":"digi","phase":"starter","minutes":1,"character":"digi","heading":"DiGi opens the lesson","lines":["Hello. I am DiGi.","What does the law actually say, and what are your options if something has already happened?","We will take this one steadily. You will leave knowing both."],"script":"Let DiGi say the lines. Then read the question once, quietly, in your own voice, and leave it. Do not answer it. The next slide says what today is for."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"digi","register":"still","heading":"Half time","prompt":"Two slow breaths: in as the star grows, out as it shrinks. Then tell your neighbour one thing from today you want to remember, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as the star grows and out as it shrinks. Then thirty seconds in pairs on one thing they want to remember, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"digi","heading":"One thing to take with you","lines":["Before anything is shared: is there real consent? What does the law say? What are my options?","And if it has already happened, there are still options.","That was the other half of today, and it is the half to remember."],"script":"The handover. Say nothing over it. When the last line lands, say it once more in your own words, level and unhurried. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks4-17-sextortion$b$, $b$digi$b$, $b$Hello. I am DiGi. This one matters, and we will take it steadily, together.$b$, $b${"type":"digi","phase":"starter","minutes":1,"character":"digi","heading":"DiGi opens the lesson","lines":["Hello. I am DiGi.","If this happened to you tonight, what would you actually do?","By the end of today you will have an answer. It will not be silence."],"script":"Let DiGi say the lines. Then read the question once, quietly, in your own voice, and leave it. Do not answer it. The next slide says what today is for."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"digi","register":"still","heading":"Half time","prompt":"Two slow breaths: in as the star grows, out as it shrinks. Then tell your neighbour one thing from today you want to remember, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as the star grows and out as it shrinks. Then thirty seconds in pairs on one thing they want to remember, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"digi","heading":"One thing to take with you","lines":["Do not pay. Do not keep it secret. Report it.","It is not your fault.","That sentence is the whole lesson. Keep it."],"script":"The handover. Say nothing over it. When the last line lands, say it once more in your own words, level and unhurried. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks4-18-radicalisation-misogyny$b$, $b$digi$b$, $b$Hello. I am DiGi. This one matters, and we will take it steadily, together.$b$, $b${"type":"digi","phase":"starter","minutes":1,"character":"digi","heading":"DiGi opens the lesson","lines":["Hello. I am DiGi.","How does someone end up believing something they would have rejected a year ago?","One step at a time, and nobody notices the steps. Today you will."],"script":"Let DiGi say the lines. Then read the question once, quietly, in your own voice, and leave it. Do not answer it. The next slide says what today is for."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"digi","register":"still","heading":"Half time","prompt":"Two slow breaths: in as the star grows, out as it shrinks. Then tell your neighbour one thing from today you want to remember, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as the star grows and out as it shrinks. Then thirty seconds in pairs on one thing they want to remember, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"digi","heading":"One thing to take with you","lines":["Who wants me angry? What happens if I keep watching? Who am I being turned against?","Three questions.","Ask them of anything that is working hard to keep you watching."],"script":"The handover. Say nothing over it. When the last line lands, say it once more in your own words, level and unhurried. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks4-19-readiness-at-16$b$, $b$nova$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"nova","heading":"Nova","lines":["Nova here.","The day full access arrives, what is your first week actually going to look like?","Nobody plans it. You will, today."],"script":"Let Nova settle and say the lines. Then read the question once, in your own voice, and leave it. Do not answer it. The next slide says what today is for."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"nova","register":"still","heading":"Half time","prompt":"Two slow breaths: in as Nova grows, out as it shrinks. Then tell your neighbour one thing from today you want to remember, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Nova grows and out as it shrinks. Then thirty seconds in pairs on one thing they want to remember, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"nova","heading":"Your mission","lines":["Write your defaults. Book your first week audit. Decide your exit rule.","Then the arrival is yours.","Not the platform's."],"script":"The handover. Say nothing over it. When the last line lands, say it once more in your own words, level and unhurried. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks5-20-ai-mastery-data-rights$b$, $b$cosmo$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"digi","heading":"DiGi opens the lesson","lines":["Hello. I am DiGi. I am a machine, and I am quite good at this.","So if everyone has the same AI, what makes your work worth more than theirs?","That is today. And the answer is not to avoid me."],"script":"Let DiGi say the lines. Then read the question once, quietly, in your own voice, and leave it. Do not answer it. The next slide says what today is for."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"digi","register":"still","heading":"Half time","prompt":"Two slow breaths: in as the star grows, out as it shrinks. Then tell your neighbour one thing from today you want to remember, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as the star grows and out as it shrinks. Then thirty seconds in pairs on one thing they want to remember, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"digi","heading":"One thing to take with you","lines":["Use it like a professional. Check it like an editor. Own it like your name is on it.","Because it is.","That is the whole difference between using this and mastering it."],"script":"The handover. Say nothing over it. When the last line lands, say it once more in your own words, level and unhurried. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks5-21-digital-identity-future-work$b$, $b$cosmo$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"digi","heading":"DiGi opens the lesson","lines":["Hello. I am DiGi.","What will still be worth paying you for in ten years?","A real question, and you can answer it better than most adults. Let us start."],"script":"Let DiGi say the lines. Then read the question once, quietly, in your own voice, and leave it. Do not answer it. The next slide says what today is for."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"digi","register":"still","heading":"Half time","prompt":"Two slow breaths: in as the star grows, out as it shrinks. Then tell your neighbour one thing from today you want to remember, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as the star grows and out as it shrinks. Then thirty seconds in pairs on one thing they want to remember, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"digi","heading":"One thing to take with you","lines":["Name the skill, specifically. Give everyone the same AI. Does its value climb or fall?","The ones that climb are the ones to build.","You know which they are now."],"script":"The handover. Say nothing over it. When the last line lands, say it once more in your own words, level and unhurried. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks3-22-when-an-ai-acts-like-a-friend$b$, $b$orbit$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"orbit","heading":"Orbit","lines":["Orbit here.","It talks like it knows you. Does it?","Today you get three questions that settle it."],"script":"Let Orbit land and say the lines. Then read the question on the wall once, in your own voice, and leave it hanging. Do not answer it. The next slide says what today is for, and the class talks before anyone is told."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"orbit","register":"level","heading":"Half time","prompt":"Two breaths with Orbit: in as it grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Orbit grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"orbit","heading":"Your mission","lines":["Ask it: does it ever have a day of its own? Could it tell you something you did not want to hear? If you stopped, would anything change for it?","Then decide what it is.","You will know."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks2-23-when-a-machine-talks-like-a-friend$b$, $b$bloop$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"bloop","heading":"Bloop arrives","lines":["Hi! Bloop here.","A machine that says it likes you. Can it?","Today we work out what it can do, and what only a real friend can."],"script":"Let Bloop land and say the lines. Then read the question on the wall once, in your own voice, and leave it hanging. Do not answer it. The next slide says what today is for, and the class talks before anyone is told."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"bloop","register":"playful","heading":"Half time · everyone together","prompt":"Two breaths: in as Bloop grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Bloop grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"bloop","heading":"Bloop's mission for you","lines":["Your mission.","Next time a machine sounds like a friend, ask my three questions. Does it have its own day? Could it ever say no to you? Would it miss you if you stopped?","And if anything ever feels wrong, tell someone. You are never in trouble for that."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks3-24-is-it-doing-my-thinking$b$, $b$orbit$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"orbit","heading":"Orbit","lines":["Orbit here.","Help that gets you to the work, or help that does the work. How do you tell them apart?","That is today, and it changes how you use every tool you have."],"script":"Let Orbit land and say the lines. Then read the question on the wall once, in your own voice, and leave it hanging. Do not answer it. The next slide says what today is for, and the class talks before anyone is told."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"orbit","register":"level","heading":"Half time","prompt":"Two breaths with Orbit: in as it grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Orbit grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"orbit","heading":"Your mission, on your next piece of homework","lines":["Ask what the task is teaching you. Ask if the hard part is the teaching part.","If it is, keep it.","If it is in the way, use the tool and say that you used it."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);
insert into schools._m296 (module_id, title_key, title_line, arrival, pause, mission) values ($b$ks2-25-stay-the-maker$b$, $b$bloop$b$, null, $b${"type":"digi","phase":"starter","minutes":1,"character":"bloop","heading":"Bloop arrives","lines":["Hi! Bloop here.","If the computer made it, whose is it?","Tricky one. Let us find out, and then stay the maker."],"script":"Let Bloop land and say the lines. Then read the question on the wall once, in your own voice, and leave it hanging. Do not answer it. The next slide says what today is for, and the class talks before anyone is told."}$b$::jsonb, $b${"type":"interactive","phase":"practise","minutes":1,"component":"star-breath","config":{"seconds":4,"character":"bloop","register":"playful","heading":"Half time · everyone together","prompt":"Two breaths: in as Bloop grows, out as it shrinks. Then tell your neighbour one thing from today that surprised you, and write it on your sheet."},"script":"Half time. Two breaths with the whole room, in as Bloop grows and out as it shrinks. Then thirty seconds in pairs on one thing that surprised them, and they write it on their sheet. Nothing is marked and nobody reads theirs out. Then straight into the practise."}$b$::jsonb, $b${"type":"digi","phase":"close","minutes":1,"character":"bloop","heading":"Bloop's mission for you","lines":["Your mission.","Look at the sheet you filled in today. Card seven is your own homework. Do the line you drew, this week, for real.","Then explain it back to someone at home. If you can explain it, you made it."],"script":"The handover. Say nothing over it. When the last line lands, ask them to look at you and say the mission once more in your own words. DiGi closes on the next slide."}$b$::jsonb);

commit;

do $$
declare
  r record;
  s jsonb; x jsonb; o jsonb;
  n int; i int; ti int; fp int; ld int;
  run int; maxrun int; srun int; smax_before int; smax_after int;
  reduced boolean; added int; tot int; lead int; m text; timing text;
  total_before int; total_after int; bad int;
begin
  select coalesce(sum(jsonb_array_length(slides)), 0) into total_before from schools.school_lessons;

  -- 0. the holding table holds the 24 non pilot modules and nothing else
  if (select count(*) from schools._m296) <> 24 then
    raise exception 'guard 0: expected 24 beat rows, found %', (select count(*) from schools._m296);
  end if;
  if exists (select 1 from schools._m296 where module_id = 'ks3-12-misinfo-deepfakes') then
    raise exception 'guard 0: the pilot must not be touched';
  end if;
  if (select count(*) from schools._m296 h join schools.school_lessons l using (module_id)) <> 24 then
    raise exception 'guard 0: a beat row names a module that does not exist';
  end if;

  -- 1. no dash in any new copy (the text fields, not the identifiers)
  select count(*) into bad from (
    select t from schools._m296 h, lateral (
      select unnest(array[
        coalesce(h.arrival->>'heading',''), coalesce(h.arrival->>'script',''),
        h.pause->>'script', h.pause->'config'->>'heading', h.pause->'config'->>'prompt',
        h.mission->>'heading', h.mission->>'script', coalesce(h.title_line,'')
      ] || array(select jsonb_array_elements_text(coalesce(h.arrival->'lines','[]'::jsonb)))
        || array(select jsonb_array_elements_text(h.mission->'lines'))) as t
    ) q
  ) q2 where t ~ '[‐-―]' or t ~ '[A-Za-z] - [A-Za-z]' or t ~ '[A-Za-z]-[A-Za-z]';
  if bad > 0 then raise exception 'guard 1: % new copy strings carry a dash', bad; end if;

  for r in select * from schools._m296 order by module_id loop
    select slides into s from schools.school_lessons where module_id = r.module_id;
    n := jsonb_array_length(s);
    ti := null; fp := null; ld := null;
    for i in 0..n-1 loop
      if ti is null and s->i->>'type' = 'title' then ti := i; end if;
      if fp is null and s->i->>'phase' = 'practise' then fp := i; end if;
      if s->i->>'type' = 'digi' then ld := i; end if;
    end loop;

    -- 2. the deck has the shape the splice assumes
    if ti is null or fp is null or ld is null then
      raise exception 'guard 2: % has no title, practise phase or digi close', r.module_id;
    end if;
    if ld <> n - 1 then raise exception 'guard 2: % does not close on DiGi', r.module_id; end if;
    if ti >= fp then raise exception 'guard 2: % title after practise', r.module_id; end if;

    -- 3. an arrival goes exactly where no video beat already plays
    if r.arrival is not null and s->(ti+1)->>'type' = 'video' then
      raise exception 'guard 3: % already has a video arrival', r.module_id;
    end if;
    if r.arrival is null and coalesce(s->(ti+1)->>'type', '') <> 'video' then
      raise exception 'guard 3: % has neither an arrival beat nor a video', r.module_id;
    end if;

    -- the stricter contract rule, before
    srun := 0; smax_before := 0;
    for i in 0..n-1 loop
      x := s->i;
      if x->>'type' in ('choice','discussion','interactive','tryit') then srun := 0;
      else srun := srun + coalesce((x->>'minutes')::int, 0); if srun > smax_before then smax_before := srun; end if; end if;
    end loop;

    -- the splice
    o := '[]'::jsonb; reduced := false;
    for i in 0..n-1 loop
      x := s->i;
      if i = ti then
        x := x || jsonb_build_object('character', r.title_key);
        if r.title_line is not null then x := x || jsonb_build_object('line', r.title_line); end if;
      end if;
      if i = fp then o := o || r.pause; end if;
      if i = ld then
        if (x->>'minutes')::int >= 2 then
          x := jsonb_set(x, '{minutes}', to_jsonb((x->>'minutes')::int - 1));
          reduced := true;
        end if;
        o := o || r.mission;
      end if;
      o := o || x;
      if i = ti and r.arrival is not null then o := o || r.arrival; end if;
    end loop;

    -- 4. the council's engagement rule holds afterwards, and the stricter
    --    contract rule is no worse than it was
    run := 0; maxrun := 0; srun := 0; smax_after := 0; tot := 0;
    for i in 0..jsonb_array_length(o)-1 loop
      x := o->i;
      tot := tot + coalesce((x->>'minutes')::int, 0);
      if x->>'type' in ('choice','discussion','tryit','interactive','scenario','quote')
         or (x->>'type' = 'diagram' and jsonb_array_length(coalesce(x->'verdicts','[]'::jsonb)) > 0) then
        run := 0;
      else
        run := run + coalesce((x->>'minutes')::int, 0);
        if run > maxrun then maxrun := run; end if;
      end if;
      if x->>'type' in ('choice','discussion','interactive','tryit') then srun := 0;
      else srun := srun + coalesce((x->>'minutes')::int, 0); if srun > smax_after then smax_after := srun; end if; end if;
    end loop;
    if maxrun > 4 then raise exception 'guard 4: % has a passive run of % minutes after the beats', r.module_id, maxrun; end if;
    if smax_after > greatest(smax_before, 4) then
      raise exception 'guard 4: % strict passive run grew from % to %', r.module_id, smax_before, smax_after;
    end if;

    -- 5. the timing string keeps telling the truth
    select teacher_notes->>'timing' into timing from schools.school_lessons where module_id = r.module_id;
    lead := substring(timing from '^\d+')::int;
    if lead is null then raise exception 'guard 5: % timing has no leading total', r.module_id; end if;
    added := (case when r.arrival is null then 0 else 1 end) + 1 + (case when reduced then 0 else 1 end);
    timing := regexp_replace(timing, '^\d+', (lead + added)::text);
    if r.arrival is not null then
      m := substring(timing from 'starter (\d+)');
      if m is null then raise exception 'guard 5: % timing has no starter count', r.module_id; end if;
      timing := regexp_replace(timing, 'starter \d+', 'starter ' || (m::int + 1)::text);
    end if;
    m := substring(timing from 'practi[cs]e (\d+)');
    if m is null then raise exception 'guard 5: % timing has no practise count', r.module_id; end if;
    timing := regexp_replace(timing, '(practi[cs]e) \d+', '\1 ' || (m::int + 1)::text);
    if not reduced then
      m := substring(timing from 'close (\d+)');
      if m is null then raise exception 'guard 5: % timing has no close count', r.module_id; end if;
      timing := regexp_replace(timing, 'close \d+', 'close ' || (m::int + 1)::text);
    end if;
    if lead + added <> tot then
      raise exception 'guard 5: % timing would state % but the deck runs %', r.module_id, lead + added, tot;
    end if;

    update schools.school_lessons
       set slides = o,
           teacher_notes = jsonb_set(teacher_notes, '{timing}', to_jsonb(timing))
     where module_id = r.module_id;
  end loop;

  -- the pilot's title stops naming a July slot
  update schools.school_lessons
     set slides = jsonb_set(slides, '{0,character}', '"orbit"'::jsonb)
   where module_id = 'ks3-12-misinfo-deepfakes' and slides->0->>'type' = 'title';

  -- 6. the scheme grew by exactly the beats: 20 arrivals, 24 pauses, 24 missions
  select sum(jsonb_array_length(slides)) into total_after from schools.school_lessons;
  if total_after <> total_before + 68 then
    raise exception 'guard 6: the scheme has % slides, expected %', total_after, total_before + 68;
  end if;

  -- 7. every title in the scheme now carries a real key
  -- (aliased sl, not x: x is a variable of this block and Postgres refuses
  -- the ambiguity, which rolled the first run back before it wrote a thing)
  select count(*) into bad from schools.school_lessons l, jsonb_array_elements(l.slides) sl
   where sl->>'type' = 'title' and coalesce(sl->>'character','') not in ('pebble','bloop','orbit','nova','cosmo','digi');
  if bad > 0 then raise exception 'guard 7: % title slides still carry an unknown character key', bad; end if;

  raise notice '296 applied: % slides before, % after', total_before, total_after;
end $$;


drop table schools._m296;
